// Intent-aware gratitude matching: recognition and requests are scored separately.
// References are curated for their immediate context; avoid generic distress verses
// when a prayer primarily expresses thanks, faith, humility, or love.
const prayerGrowthThemes=[
 {id:'gratitude',title:'Give Thanks for His Goodness',pattern:/\b(thank(?:s|ful|sgiving)?|grateful|gratitude|bless(?:ed|ings)?|prais(?:e|ing)?|appreciat(?:e|ion)|goodness|provision|gift(?:s)?|rejoic(?:e|ing)|worship)\b/gi,refs:['1 Thessalonians 5:18','Psalm 100:4','James 1:17','Psalm 103:2'],prayer:'Thank You for Your goodness and the blessings received. Grow a grateful heart that remembers Your gifts and responds with praise.'},
 {id:'faith',title:'Grow in Faith and Trust',pattern:/\b(faith|faithful|believ(?:e|ing)|trust|grow closer to god|closer to you|know god|knowledge of god)\b/gi,refs:['Luke 17:5','Colossians 2:6','Hebrews 11:6','2 Peter 3:18'],prayer:'Deepen their faith and knowledge of You; help them trust and follow You day by day.'},
 {id:'humility',title:'Walk Humbly With God',pattern:/\b(humbl(?:e|eness|y)|humility|pride|proud|meek(?:ness)?|servant.heart)\b/gi,refs:['Micah 6:8','Philippians 2:3','James 4:10','1 Peter 5:5'],prayer:'Teach them humility, gentleness, and a willingness to put others before themselves.'},
 {id:'love',title:'Let Your Love Grow',pattern:/\b(love for others|loving others|love one another|grow in love|show love|loving people|compassion|kindness|care for others|serve others)\b/gi,refs:['1 John 4:7','Philippians 1:9','John 13:34','1 Corinthians 13:4'],prayer:'Let Your love shape how they treat others, with patience, kindness, and compassion.'}
];
function prayerGrowthMatches(request){
 const lower=request.toLowerCase();
 return prayerGrowthThemes.map((t,i)=>{
   const hits=(lower.match(t.pattern)||[]).length;
   const requestFocus=t.id==='gratitude'?/\b(thank you|thank god|thankful|grateful|gratitude|blessings|praise)\b/i.test(request):
      t.id==='faith'?/\b(grow|increase|deepen|strengthen|build|develop|more)\b.{0,35}\b(faith|trust|knowledge of god)\b/i.test(request):
      t.id==='humility'?/\b(grow|increase|deepen|learn|be|become|more)\b.{0,30}\b(humbl|humility|meek)/i.test(request):
      /\b(grow|increase|deepen|show|share|have|more)\b.{0,35}\b(love|compassion|kindness)\b/i.test(request);
   return {...t,score:hits*3+(requestFocus?5:0),order:i};
 }).filter(t=>t.score>0).sort((a,b)=>b.score-a.score||a.order-b.order);
}
