// Installation UI is independent of prayer and journal storage.
let installPrompt=null;
let installOpen=false;
let updateReady=false;
const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const appleMobile=()=>/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const android=()=>/Android/i.test(navigator.userAgent);
function welcomeSeen(){try{return localStorage.getItem('rl-install-welcome-v3')==='1'}catch{return false}}
function dismissWelcome(){try{localStorage.setItem('rl-install-welcome-v3','1')}catch{}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;installBanner()});
window.addEventListener('appinstalled',()=>{installPrompt=null;installOpen=false;dismissWelcome();installBanner()});
matchMedia('(display-mode: standalone)').addEventListener?.('change',installBanner);
function installBanner(){
 const root=$('#install');if(!root)return;
 const standalone=installed();
 const welcome=!standalone&&!welcomeSeen();
 document.documentElement.classList.toggle('rl-standalone',standalone);
 const glyph=(path)=>`<svg aria-hidden="true" viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
 const compass=glyph('<circle cx="12" cy="12" r="10"/><path d="m16 8-3 5-5 3 3-5z"/>');
 const share=glyph('<path d="M8 9H5v12h14V9h-3M12 15V2m-4 4 4-4 4 4"/>');
 const plus=glyph('<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M12 7v10M7 12h10"/>');
 const toggle=glyph('<rect x="2" y="6" width="20" height="12" rx="6" fill="#27834d" stroke="#27834d"/><circle cx="16" cy="12" r="4" fill="white" stroke="white"/>');
 const chrome=glyph('<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="4"/><path d="M12 8h9M8.5 14 4 6m11 8-5 8"/>');
 const menu=glyph('<circle cx="12" cy="5" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="12" cy="19" r="1"/>');
 const step=(icon,text)=>`<li>${icon}<span>${text}</span></li>`;
 const help=appleMobile()?`<ol class="rl-install-steps">${step(compass,'Open this page in <strong>Safari</strong>, not an embedded browser.')}${step(share,'Tap the <strong>Safari toolbar Share icon</strong> (square with upward arrow). Do not use the RightLens Share button.')}${step(plus,'Scroll to <strong>Add to Home Screen</strong> in Safari’s share menu.')}${step(toggle,'Enable <strong>Open as Web App</strong> if shown, then tap <strong>Add</strong>.')}</ol>`:android()?`<ol class="rl-install-steps">${step(chrome,'Open this page in <strong>Chrome</strong>.')}${step(menu,'Tap Chrome’s three-dot menu, usually in the upper-right corner.')}${step(plus,'Choose <strong>Install app</strong> or <strong>Add to Home screen</strong>, then confirm Install or Add. Wording may vary.')}</ol>`:'<p>In Chrome or Edge, look for the install icon in the address bar or Install app in the browser menu. On supported Mac Safari versions, choose File → Add to Dock.</p>';
 root.innerHTML=`<section class="rl-install-panel" aria-label="RightLens installation and sharing">${welcome?'<div class="rl-welcome"><img src="/icon-192.png" alt=""><div><strong>Welcome to RightLens</strong><p>Discover Scripture, explore your identity in Christ, and receive a Word, Scripture, and Prayer through WordUp. Free to use; no account required.</p></div></div>':''}<div class="rl-install-actions">${standalone?'':'<button type="button" class="gold-btn" id="rl-install-now" aria-expanded="'+installOpen+'">Install RightLens</button>'}<button type="button" class="subtle" id="rl-share">Share RightLens</button>${welcome?'<button type="button" class="subtle" id="rl-continue">Continue without installing</button>':''}${updateReady?'<button type="button" class="subtle" id="rl-update">Update available · Reload when ready</button>':''}</div>${!standalone&&installOpen?'<div class="rl-install-help"><strong>How to install</strong>'+help+'<button type="button" class="subtle" id="rl-close-help">Close instructions</button></div>':''}<p id="rl-install-status" role="status" hidden></p><div id="rl-share-fallback" hidden><label for="rl-share-url">Copy this public link</label><input id="rl-share-url" readonly value="https://right-lens.vercel.app/"></div></section>`;
 const status=msg=>{const el=$('#rl-install-status');el.hidden=false;el.textContent=msg};
 const install=$('#rl-install-now');if(install)install.onclick=async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;try{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted'){dismissWelcome();installOpen=false;installBanner();return}}catch{} }installOpen=!installOpen;installBanner();$('#rl-install-now')?.focus()};
 const close=$('#rl-close-help');if(close)close.onclick=()=>{installOpen=false;installBanner();$('#rl-install-now')?.focus()};
 const next=$('#rl-continue');if(next)next.onclick=()=>{dismissWelcome();installOpen=false;installBanner();$('#hero-start')?.focus()};
 $('#rl-share').onclick=async()=>{const url='https://right-lens.vercel.app/';if(navigator.share){try{await navigator.share({title:'RightLens',text:'See life through Scripture',url});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(url);status('RightLens link copied.')}catch{const fallback=$('#rl-share-fallback');fallback.hidden=false;$('#rl-share-url').select();status('Select and copy the link below.')}};
 const update=$('#rl-update');if(update)update.onclick=()=>{if(confirm('Reload RightLens? Any unsaved text will be lost. Saved journal entries will remain.'))location.reload()};
}
function registerRightLensWorker(){
 if(!('serviceWorker' in navigator))return;
 let controlled=!!navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(controlled){updateReady=true;installBanner()}controlled=true});
 navigator.serviceWorker.register('/sw.js').catch(()=>{});
}
fetch('/verses.json').then(r=>{if(!r.ok)throw Error('Unable to load index');return r.json()}).then(async v=>{verses=v;const [r,n]=await Promise.all([fetch('/rvu.json').then(r=>r.ok?r.json():{R:[],U:[]}).catch(()=>({R:[],U:[]})),fetch('/names.json').then(r=>r.ok?r.json():[]).catch(()=>[])]);studyData=r;nameData=n;shell();registerRightLensWorker()}).catch(e=>{$('#app').textContent='Unable to load RightLens. Please reconnect once to download the offline library.';console.error(e)});


// Full Bible: verse-by-verse BSB and KJV, self-hosted and loaded per book.
let bibleBooks=null;const bibleCache=new Map();let bibleVersion='bsb',bibleCompare=false,bibleTerm='',bibleResults=[];
async function bibleList(){if(!bibleBooks){const r=await fetch('/bible/books.json');if(!r.ok)throw Error('Bible book list unavailable');bibleBooks=await r.json()}return bibleBooks}
async function loadBibleBook(book,version){const k=version+'|'+book;if(bibleCache.has(k))return bibleCache.get(k);const r=await fetch('/bible/'+version+'-'+book.toLowerCase().replace(/ /g,'-')+'.json');if(!r.ok)throw Error('Bible book unavailable: '+book);const data=await r.json();bibleCache.set(k,data);return data}
async function getBibleVerse(ref,version='bsb'){const books=await bibleList();const b=books.find(x=>ref.startsWith(x+' '));if(!b)return '';const data=await loadBibleBook(b,version);return data[ref]||''}
async function searchFullBible(term,version='bsb',limit=100){const books=await bibleList();const terms=term.toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>3&&!['please','would','could','have','with','from','this','that','about','there','their','what','when','where','need','prayer','pray','help'].includes(x));const phrase=term.trim().toLowerCase();let results=[];for(const book of books){const data=await loadBibleBook(book,version);for(const [ref,text] of Object.entries(data)){const t=text.toLowerCase();const hits=terms.reduce((n,w)=>n+(t.includes(w)?1:0),0);if(hits||t.includes(phrase)&&phrase){results.push({ref,text,score:hits+(t.includes(phrase)?4:0)})}}}results.sort((a,b)=>b.score-a.score);return results.slice(0,limit)}
async function renderBible(){const books=await bibleList();$('#content').innerHTML=`<section class="section-heading"><span class="eyebrow dark">66 BOOKS · TWO TRANSLATIONS</span><h2>Explore the Full Bible</h2><p>Search every verse of the Berean Standard Bible or King James Version. No Bible API or download required.</p></section><section class="search-panel"><label for="bible-q">Search Scripture or enter a reference</label><div class="searchline"><input id="bible-q" type="search" placeholder="peace, love, Genesis 1:1..." value="${esc(bibleTerm)}"><button id="bible-search" class="gold-btn">Search</button></div><div class="mode"><label for="bible-version">Translation </label><select id="bible-version"><option value="bsb" ${bibleVersion==='bsb'?'selected':''}>BSB — Berean Standard Bible</option><option value="kjv" ${bibleVersion==='kjv'?'selected':''}>KJV — King James Version</option></select><label><input type="checkbox" id="bible-compare" ${bibleCompare?'checked':''}> Compare BSB + KJV</label></div><p id="bible-status" aria-live="polite">${bibleResults.length?bibleResults.length+' results shown':'Enter a search to explore all 66 books.'}</p></section><div id="bible-results"></div>`;
$('#bible-version').onchange=e=>{bibleVersion=e.target.value};$('#bible-compare').onchange=e=>{bibleCompare=e.target.checked};$('#bible-q').onkeydown=e=>{if(e.key==='Enter')$('#bible-search').click()};$('#bible-search').onclick=async()=>{const term=$('#bible-q').value.trim();if(!term)return;bibleTerm=term;const status=$('#bible-status');status.textContent='Searching Scripture…';const btn=$('#bible-search');btn.disabled=true;try{const direct=/^(.+?)\s+(\d+):(\d+)$/.exec(term);if(direct&&books.includes(direct[1])){const ref=term;const text=await getBibleVerse(ref,bibleVersion);bibleResults=text?[{ref,text,score:1}]:[]}else bibleResults=await searchFullBible(term,bibleVersion,100);status.textContent=bibleResults.length+' results shown (up to 100; search again to refine)';await drawBibleResults()}catch(e){status.textContent='Could not load Bible text. Check your connection and retry.';console.error(e)}finally{btn.disabled=false}};
if(bibleResults.length)await drawBibleResults()}
async function drawBibleResults(){const node=$('#bible-results');if(!node)return;let html='';for(const item of bibleResults){const second=bibleCompare?await getBibleVerse(item.ref,bibleVersion==='bsb'?'kjv':'bsb'):null;html+=`<article class="bible-result"><h3>${esc(item.ref)}</h3><div class="bible-compare-grid"><div><strong>${bibleVersion.toUpperCase()}</strong><p>${esc(item.text)}</p></div>${second!==null?`<div><strong>${bibleVersion==='bsb'?'KJV':'BSB'}</strong><p>${esc(second)}</p></div>`:''}</div></article>`}node.innerHTML=html||'<p>No matching verses. Try another search.</p>'}
